const root = 'C:/Users/HP/Downloads/SunuPermis';
const pages = [
  {name:'Accueil', file:root+'/index.html'},
  {name:'Administration', file:root+'/admin.html'},
  {name:'Carte du Sénégal', file:root+'/carte-senegal.html'},
  {name:'Code de la route', file:root+'/code-route.html'},
  {name:'Conduite', file:root+'/conduire.html'},
  {name:'Conseils examen', file:root+'/conseils-examen.html'},
  {name:'Examen blanc', file:root+'/examen.html'},
  {name:'Glossaire', file:root+'/glossaire.html'},
  {name:'Manœuvres', file:root+'/manoeuvres.html'},
  {name:'Offres', file:root+'/offres.html'},
  {name:'Choix du permis', file:root+'/permis.html'},
  {name:'Priorités', file:root+'/priorites.html'},
  {name:'Profil', file:root+'/profil.html'},
  {name:'Progression', file:root+'/progression.html'},
  {name:'Quiz', file:root+'/quiz.html'},
  {name:'Vidéothèque', file:root+'/videotheque.html'}
];
const itemSchema = JSON.stringify({type:'object',properties:{target:{type:'string'},summary:{type:'string'},findings:{type:'array',items:{type:'object',properties:{severity:{type:'string',enum:['critique','élevée','moyenne','faible','information']},category:{type:'string'},issue:{type:'string'},evidence:{type:'string'},proposed_fix:{type:'string'},confidence:{type:'string',enum:['élevée','moyenne','faible']}},required:['severity','category','issue','evidence','proposed_fix','confidence']}}},required:['target','summary','findings']});
const pageResults = await parallel('Audit HTML et interactions des 16 pages', () => pages.map(page => agent(
  'Tu réalises un audit en lecture seule de la page SunuPermis «'+page.name+'» ('+page.file+'). Inspecte précisément le fichier fourni : structure HTML, liens/scripts locaux, balises mal imbriquées, contrôles et formulaires, labels, boutons, rôles/ARIA, identifiants et références dans le JS inline, logique inline manifestement erronée, styles/couleurs inline ou lisibilité. Rapporte uniquement des défauts vérifiables, avec preuve exploitable (ligne, sélecteur, identifiant ou extrait court), gravité, correctif proposé et confiance. Écarte les préférences subjectives et les problèmes que les éléments fournis ne permettent pas d’établir. Ne modifie aucun fichier. Retourne le schéma demandé en français.',
  {brief:'Auditer la page '+page.name, input_files:[{path:page.file,name:'page.html'}], sandbox:'shared', effort_level:'standard'}
)), {schema:itemSchema});
const sharedResult = await agent(
  'Audite en lecture seule les éléments communs de SunuPermis, uniquement à partir des fichiers fournis : css/style.css, js/layout.js, js/main.js, js/api.js, js/raoul-chat.js et sw.js. Cherche des erreurs de couleur vérifiables (contrastes manifestement faibles, couleurs incohérentes, texte illisible selon thèmes), règles CSS qui neutralisent hidden/focus/états, problèmes responsive, contrôles clavier/ARIA, bugs de fermeture/ouverture des widgets, ordres/états de script et invalidation du cache. Confirme chaque défaut par règle ou ligne/extrait court et propose un correctif minimal. Ne modifie aucun fichier, ne signale pas les préférences esthétiques comme des bugs. Retourne le schéma demandé en français.',
  {brief:'Auditer styles et scripts communs', input_files:[{path:root+'/css/style.css',name:'style.css'},{path:root+'/js/layout.js',name:'layout.js'},{path:root+'/js/main.js',name:'main.js'},{path:root+'/js/api.js',name:'api.js'},{path:root+'/js/raoul-chat.js',name:'raoul-chat.js'},{path:root+'/sw.js',name:'sw.js'}], sandbox:'shared', effort_level:'standard', schema:itemSchema}
);
const successful = pageResults.filter(r=>r.ok).map(r=>r.value);
const failures = pageResults.map((r,i)=>r.ok?null:{target:pages[i].name,code:r.error.code,message:r.error.message}).filter(Boolean);
const shared = sharedResult.ok?sharedResult.value:null;
const reducerSchema = JSON.stringify({type:'object',properties:{summary:{type:'string'},findings:{type:'array',items:{type:'object',properties:{target:{type:'string'},severity:{type:'string',enum:['critique','élevée','moyenne','faible','information']},category:{type:'string'},issue:{type:'string'},evidence:{type:'string'},proposed_fix:{type:'string'},confidence:{type:'string',enum:['élevée','moyenne','faible']},duplicate_of:{type:'string'}},required:['target','severity','category','issue','evidence','proposed_fix','confidence','duplicate_of']}},coverage_gaps:{type:'array',items:{type:'string'}}},required:['summary','findings','coverage_gaps']});
const reduced = await agent(
  'Synthétise les résultats d’audit suivants, sans réinspecter les fichiers. Élimine les doublons entre pages et composants communs, ne conserve que les anomalies vérifiables, garde les preuves fournies, classe par priorité de correction et note toute couverture manquante. Si une divergence de résultats n’est pas résolue par les preuves, marque la confiance faible au lieu de trancher. Résultats page par page: '+JSON.stringify(successful)+'; audit commun: '+JSON.stringify(shared)+'; échecs de couverture: '+JSON.stringify(failures)+'. Retourne le schéma demandé en français.',
  {brief:'Synthétiser les défauts confirmés', sandbox:'shared', effort_level:'standard', schema:reducerSchema}
);
return {page_count:pages.length,successful_pages:successful.length,failures,shared_result:shared,reduced:reduced.ok?reduced.value:null,reducer_failure:reduced.ok?null:{code:reduced.error.code,message:reduced.error.message}};

